export type TsysTierSummary = {
	tier_id: string,
	min_level: number,
	max_level: number,
	min_rarity: string | null,
	skill_level_prereq: number | null,
	effects: string[],
	icon_id: number | null,
};

export type UnmetRequirement = {
	skill_name: string,
	required: number,
	current: number,
};

/**  A base value and its build-modified effective value, with the mods responsible. */
export type ValueBreakdown = {
	base: number | null,
	effective: number | null,
	/**  Flat amount added by mods (before/with the % multipliers). */
	added: number | null,
	/**  Base-only percentage total (fraction, e.g. 0.45 == +45%). Damage only. */
	base_pct: number | null,
	/**  All-damage percentage total (fraction). */
	all_pct: number | null,
	contributions: ContributionLine[],
	/**  True when the base was zero but a mod made it non-zero (dormant → active). */
	dormant_activated: boolean,
};

/**  A compact item summary for vendor inventory display. */
export type VendorItemSummary = {
	item_id: number,
	name: string,
	value: number | null,
	icon_id: number | null,
};

/**  Get the NPC keys and names that sell/barter a given item (for item tooltips). */
export type VendorNpcSummary = {
	npc_key: string,
	name: string,
};
